/**
 * Writes scripts/data/oral-glp-1-uae-market-research.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-oral-glp1-uae-cover.mjs.
 *
 *   node scripts/generate-oral-glp1-uae-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/oral-glp-1-uae-market-research.json');

export const IVONA_GUNJOVA_SANITY_ID = '5e67519a-1cdc-4b57-a881-29391db4accd';

/** Every blogPost field that applies to a healthcare-silo article. */
export const ORAL_GLP1_UAE_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-oral-glp1-uae-orforglipron.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.ORAL_GLP1_UAE_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.ORAL_GLP1_UAE_BODY_HTML.split('<h2')[0])
    .replace(/^Oral GLP-1 UAE market research[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.ORAL_GLP1_UAE_META_TITLE,
      metaDescription: mod.ORAL_GLP1_UAE_META_DESCRIPTION,
      focusKeyword: 'oral GLP-1 UAE market research',
      keywords: [
        'oral GLP-1 UAE market research',
        'orforglipron UAE',
        'Foundayo UAE',
        'oral GLP-1 UAE',
        'EDE orforglipron',
        'Wegovy pill UAE',
        'obesity market research UAE',
        'UAE market access obesity',
      ],
      canonicalUrl: mod.ORAL_GLP1_UAE_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.ORAL_GLP1_UAE_META_TITLE,
      ogDescription: mod.ORAL_GLP1_UAE_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.ORAL_GLP1_UAE_COVER_IMAGE}`,
        alt: mod.ORAL_GLP1_UAE_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.ORAL_GLP1_UAE_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.ORAL_GLP1_UAE_SLUG },
    excerpt: mod.ORAL_GLP1_UAE_EXCERPT,
    publishedAt: mod.ORAL_GLP1_UAE_PUBLISHED_ISO,
    updatedAt: mod.ORAL_GLP1_UAE_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: IVONA_GUNJOVA_SANITY_ID,
      name: 'Ivona Gunjova',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.ORAL_GLP1_UAE_HERO_IMAGE}`,
      alt: mod.ORAL_GLP1_UAE_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for oral GLP-1 UAE market research after Foundayo',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.ORAL_GLP1_UAE_TAGS],
    country: 'United Arab Emirates',
    language: 'en',
    readingTime: mod.ORAL_GLP1_UAE_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.ORAL_GLP1_UAE_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.ORAL_GLP1_UAE_EXECUTIVE_SUMMARY_HTML}\n\n${mod.ORAL_GLP1_UAE_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What oral GLP-1 UAE market research should measure after Foundayo',
        type: 'table',
        data: JSON.stringify(
          mod.ORAL_GLP1_UAE_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'WAM 3 April 2026; FDA 1 April 2026; Novo / ZAWYA 3 June 2026; MoHAP NHS 2024–25',
      },
      portableText(
        firstParagraph ||
          'Oral GLP-1 UAE market research is an uptake problem before it is a sizing problem.',
      ),
    ],
    faq: mod.ORAL_GLP1_UAE_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: ['thiqa-obesity-reimbursement-abu-dhabi', 'qatar-obesity-glp1-market-research'],
    ctaSection: { ...mod.ORAL_GLP1_UAE_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.ORAL_GLP1_UAE_BODY_HTML),
    factCheckedAt: mod.ORAL_GLP1_UAE_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/oral-glp-1-uae-market-research-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of ORAL_GLP1_UAE_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
